import { Component, computed, DestroyRef, inject, input, OnInit, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { forkJoin } from 'rxjs';
import { TramiteCatalogoItem } from '../../../../shared/models/tramite-catalogo.model';
import { Municipio, MunicipioFiltro } from '../../../../shared/models/municipio.model';
import { TramiteService } from '../../../../shared/services/tramite.service';
import { SolicitudService } from '../../../../shared/services/solicitud.service';
import { extractErrorMessage } from '../../../../shared/utils/error-utils';

@Component({
  selector: 'app-tramites-catalogo',
  imports: [CommonModule, FormsModule],
  templateUrl: './tramites-catalogo.component.html',
  styleUrl: './tramites-catalogo.component.scss',
})
export class TramitesCatalogoComponent implements OnInit {
  private readonly router = inject(Router);
  private readonly tramiteService = inject(TramiteService);
  private readonly solicitudService = inject(SolicitudService);
  private readonly destroyRef = inject(DestroyRef);

  /** Cuando es `true` el catálogo es de solo consulta y oculta la acción de iniciar trámite. */
  readonly soloLectura = input(false);

  readonly tramites = signal<TramiteCatalogoItem[]>([]);
  readonly municipios = signal<Municipio[]>([]);
  readonly isLoading = signal(true);
  readonly loadError = signal<string | null>(null);

  readonly searchQuery = signal<string>('');
  readonly selectedMunicipio = signal<MunicipioFiltro>('todos');
  readonly selectedNivel = signal<string>('todos');

  readonly tramitesFiltrados = computed(() => {
    const q = this.searchQuery().trim().toLowerCase();
    const mun = this.selectedMunicipio();
    const nivel = this.selectedNivel();

    return this.tramites().filter((t) => {
      const matchSearch =
        !q ||
        t.nombre.toLowerCase().includes(q) ||
        t.claveOficial.toLowerCase().includes(q) ||
        t.dependencia.toLowerCase().includes(q) ||
        t.descripcion.toLowerCase().includes(q);

      const matchMun = this.matchesMunicipio(t, mun);

      let matchNivel = true;
      if (nivel !== 'todos') matchNivel = t.nivelGobierno === nivel;

      return matchSearch && matchMun && matchNivel;
    });
  });

  ngOnInit(): void {
    forkJoin({
      tramites: this.tramiteService.getCatalogo(),
      municipios: this.solicitudService.getMunicipios(),
    })
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: ({ tramites, municipios }) => {
          this.tramites.set(tramites);
          this.municipios.set(municipios);
          this.isLoading.set(false);
        },
        error: (err) => {
          this.isLoading.set(false);
          this.loadError.set(extractErrorMessage(err));
        },
      });
  }

  private matchesMunicipio(tramite: TramiteCatalogoItem, filtro: MunicipioFiltro): boolean {
    if (filtro === 'todos') return true;
    if (filtro === 'estatal') return tramite.municipioId === null || tramite.nivelGobierno === 'estatal';
    return tramite.municipioId === filtro || tramite.municipioNombre === this.municipioNombre(filtro);
  }

  private municipioNombre(id: number): string {
    return this.municipios().find((m) => m.id === id)?.nombre ?? '';
  }

  iniciarTramite(tramite: TramiteCatalogoItem): void {
    void this.router.navigate(['/inversores/tramites/solicitar'], {
      queryParams: { tramiteId: tramite.id },
    });
  }
}
